-- V1__baseline_lote1.sql
-- DEC-L016: todo el ERP Logistico vive en su propio esquema (${schema},
-- placeholder de Flyway = spring.flyway.placeholders.schema, default
-- "logistica") dentro de la BD de Supabase compartida con RRHH-SYSTEM.
-- beforeMigrate.sql aborta si el esquema fuera "public". Se quitaron de esta
-- baseline las funciones/policies de Supabase Auth (auth.uid(), RLS): estaban
-- muertas desde DEC-L008 (auth propio con JWT) y no deben tocar la BD de RRHH.

-- ============================================================
-- Fuente historica: supabase/migrations/0001_init_common.sql
-- ============================================================
-- 0001_init_common.sql
-- Extensiones y utilidades compartidas por todas las tablas del ERP Logistico.


-- Trigger generico: mantiene updated_at al dia en cualquier tabla que lo tenga.
create or replace function ${schema}.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

comment on function ${schema}.set_updated_at() is
  'Trigger BEFORE UPDATE generico: setea updated_at = now(). Igual patron que RRHH-SYSTEM.';

-- ============================================================
-- Fuente historica: supabase/migrations/0002_organizacion.sql
-- ============================================================
-- 0002_organizacion.sql
-- EMPRESA, CECO, PROYECTO (grupo ORGANIZACION del diccionario de datos V38 Final).
-- proyecto.responsible_user_id referencia a USUARIO, que aun no existe -> se agrega
-- la FK diferida en 0029_fk_deferred.sql.

create table if not exists ${schema}.empresa (
  company_id uuid primary key default gen_random_uuid(),
  code       varchar(20) not null unique,   -- TDEMSRL / METRIN / GOYDELSAC
  legal_name varchar(180) not null,
  ruc        varchar(11) unique,
  active     boolean not null default true
);

comment on table ${schema}.empresa is 'Razones sociales del grupo (TDEM/METRIN/GOYDEL) y alcance multiempresa.';
comment on column ${schema}.empresa.code is
  'Mismo codigo que usa RRHH-SYSTEM (padron_personal.empresa: TDEMSRL/GOYDELSAC) para que el sync por DNI no requiera tabla de mapeo. METRIN no existe aun en RRHH.';

create table if not exists ${schema}.ceco (
  ceco_id    uuid primary key default gen_random_uuid(),
  company_id uuid not null references ${schema}.empresa(company_id),
  code       varchar(30) not null,
  name       varchar(180) not null,
  active     boolean not null default true,
  unique (company_id, code)
);

comment on table ${schema}.ceco is 'Centro de costo por empresa.';

create table if not exists ${schema}.proyecto (
  project_id           uuid primary key default gen_random_uuid(),
  company_id           uuid not null references ${schema}.empresa(company_id),
  ceco_id              uuid not null references ${schema}.ceco(ceco_id),
  project_code         varchar(50) not null,
  name                 varchar(180) not null,
  client_name          varchar(180),
  responsible_user_id  uuid,  -- FK a usuario, diferida (0029_fk_deferred.sql)
  start_date           date,
  end_date             date,
  status               varchar(30) not null default 'ACTIVO'
                         check (status in ('ACTIVO', 'CERRADO', 'SUSPENDIDO')),
  unique (company_id, project_code)
);

comment on table ${schema}.proyecto is 'Proyecto operativo asociado a empresa y CECO.';

-- Seed minimo de empresas (codigos alineados con RRHH-SYSTEM.padron_personal.empresa).
on conflict (code) do nothing;

-- ============================================================
-- Fuente historica: supabase/migrations/0003_documento.sql
-- ============================================================
-- 0003_documento.sql
-- DOCUMENTO / DOCUMENTO_RELACION (grupo DOCUMENTOS). Se crea temprano porque
-- PRODUCTO_IMAGEN, SOLICITUD_MAESTRO_PRODUCTO, COMUNICACION_PROVEEDOR,
-- COTIZACION y EXTRACCION_DOCUMENTO ya referencian document_id.
-- documento.uploaded_by referencia a USUARIO, aun no existe -> FK diferida
-- en 0029_fk_deferred.sql.

create table if not exists ${schema}.documento (
  document_id   uuid primary key default gen_random_uuid(),
  document_type varchar(40) not null
    check (document_type in (
      'COTIZACION','OC','FACTURA_PDF','FACTURA_XML','GUIA','REQUERIMIENTO',
      'NOTA_INVENTARIO','TICKET_ENVIO','CONFORMIDAD_ENTREGA','CONSTANCIA','EVIDENCIA'
    )),
  file_name    varchar(220) not null,
  file_url     text not null,          -- ruta en storage; la BD nunca guarda el binario
  mime_type    varchar(100),
  file_hash    varchar(128),           -- control de duplicidad/integridad
  uploaded_by  uuid,                   -- FK a usuario, diferida
  uploaded_at  timestamptz not null default now(),
  status       varchar(30) not null default 'ACTIVO' check (status in ('ACTIVO', 'ANULADO'))
);

comment on table ${schema}.documento is
  'Repositorio logico de archivos. El archivo fisico va a storage; aqui solo URL/hash.';

create table if not exists ${schema}.documento_relacion (
  document_relation_id uuid primary key default gen_random_uuid(),
  document_id uuid not null references ${schema}.documento(document_id),
  entity_type varchar(40) not null
    check (entity_type in (
      'REQUERIMIENTO','RFQ','COTIZACION','ORDEN','RECEPCION','FACTURA','PAGO',
      'INCIDENCIA','SALIDA','NOTA_INVENTARIO','ENVIO','GUIA_REMISION','CONFORMIDAD_ENTREGA'
    )),
  entity_id uuid not null
);

comment on table ${schema}.documento_relacion is
  'Permite vincular un mismo archivo a varias entidades (polimorfico por entity_type/entity_id).';

create index if not exists idx_documento_relacion_entity
  on ${schema}.documento_relacion (entity_type, entity_id);

-- ============================================================
-- Fuente historica: supabase/migrations/0004_seguridad.sql
-- ============================================================
-- 0004_seguridad.sql
-- ROL, PERMISO, ROL_PERMISO, USUARIO, USUARIO_ROL, USUARIO_CECO (grupo SEGURIDAD).
--
-- USUARIO es identidad/autorizacion del ERP (login + rol + CECO visible),
-- NO un mantenedor de personal. El diccionario original de Jonathan no preveia
-- la integracion con RRHH-SYSTEM, asi que se agregan 2 columnas ADITIVAS
-- (fuente, source_synced_at) fuera de su diseño base -- ver docs/04_DECISIONES.md
-- DEC-L002. El resto de columnas (employee_external_id, corporate_email,
-- display_name, identity_provider_id, active) son las que ya especifico Jonathan.

create table if not exists ${schema}.rol (
  role_id uuid primary key default gen_random_uuid(),
  code    varchar(40) not null unique,  -- SOLICITANTE / LOGISTICA / APROBADOR / ADMIN
  name    varchar(100) not null,
  active  boolean not null default true
);

comment on table ${schema}.rol is 'Roles funcionales del ERP Logistico.';

create table if not exists ${schema}.permiso (
  permission_id uuid primary key default gen_random_uuid(),
  code        varchar(80) not null unique,  -- ej. COSTO_COMPRA_VER
  module      varchar(60) not null,
  description varchar(220) not null
);

comment on table ${schema}.permiso is 'Permisos atomicos; no depender del nombre del rol para autorizar.';

create table if not exists ${schema}.rol_permiso (
  role_id       uuid not null references ${schema}.rol(role_id),
  permission_id uuid not null references ${schema}.permiso(permission_id),
  primary key (role_id, permission_id)
);

create table if not exists ${schema}.usuario (
  user_id               uuid primary key default gen_random_uuid(),
  company_id            uuid references ${schema}.empresa(company_id),  -- null = corporativo/multiempresa
  employee_external_id  varchar(50),   -- DNI/ID proveniente de RRHH-SYSTEM cuando fuente=RRHH_SYNC
  corporate_email       varchar(180) not null unique,
  display_name          varchar(180) not null,
  identity_provider_id  varchar(180), -- id en Supabase Auth
  active                boolean not null default true,

  -- Extension DEC-L002 (fuera del diccionario original de Jonathan):
  fuente             varchar(20) not null default 'MANUAL'
                        check (fuente in ('RRHH_SYNC', 'MANUAL')),
  source_synced_at   timestamptz,  -- ultima vez que personal_sync.service actualizo esta fila

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table ${schema}.usuario is
  'Identidad/autorizacion del ERP (login, rol, CECO visible). NO es mantenedor de personal: '
  'para TDEM/GOYDEL se llena por sync de solo lectura desde RRHH-SYSTEM (fuente=RRHH_SYNC); '
  'para METRIN/GOYDEL mientras RRHH no los cubra, por alta manual acotada (fuente=MANUAL).';
comment on column ${schema}.usuario.employee_external_id is
  'DNI (u otro id) proveniente de RRHH-SYSTEM. Unique parcial definido mas abajo.';

create unique index if not exists uq_usuario_employee_external_id
  on ${schema}.usuario (employee_external_id) where employee_external_id is not null;

create unique index if not exists uq_usuario_identity_provider_id
  on ${schema}.usuario (identity_provider_id) where identity_provider_id is not null;

drop trigger if exists trg_usuario_updated_at on ${schema}.usuario;
create trigger trg_usuario_updated_at
  before update on ${schema}.usuario
  for each row execute function ${schema}.set_updated_at();

create table if not exists ${schema}.usuario_rol (
  user_id    uuid not null references ${schema}.usuario(user_id),
  role_id    uuid not null references ${schema}.rol(role_id),
  company_id uuid references ${schema}.empresa(company_id),  -- null = rol aplica a todas las empresas del usuario
  primary key (user_id, role_id, company_id)
);

comment on table ${schema}.usuario_rol is 'Relacion usuario-rol por empresa (un usuario puede tener distinto rol por empresa).';

create table if not exists ${schema}.usuario_ceco (
  user_id uuid not null references ${schema}.usuario(user_id),
  ceco_id uuid not null references ${schema}.ceco(ceco_id),
  primary key (user_id, ceco_id)
);

comment on table ${schema}.usuario_ceco is 'CECO/proyectos visibles para el usuario (ambito de un SOLICITANTE/APROBADOR).';

-- Seed de roles (ver docs_base/Matriz_Funcionalidades..., hoja 07_Perfiles_V38:
-- SOLICITANTE/LOGISTICA/ADMIN; APROBADOR se agrega porque REGLA_APROBACION
-- exige rangos monetarios que el prototipo no separaba explicitamente de LOGISTICA).
on conflict (code) do nothing;

-- ============================================================
-- Fuente historica: supabase/migrations/0005_rls_seguridad.sql
-- ============================================================
-- 0005_rls_seguridad.sql
-- Helper central current_tiene_rol() (mismo patron que RRHH-SYSTEM: current_rol()
-- SECURITY DEFINER, evita recursion de RLS al leer USUARIO/USUARIO_ROL) y RLS de
-- las tablas creadas hasta ahora (empresa, ceco, proyecto, documento*, seguridad).


-- EMPRESA / CECO / PROYECTO: catalogos legibles por cualquier autenticado;
-- solo LOGISTICA/ADMIN los mantiene.


-- ROL / PERMISO / ROL_PERMISO: catalogo de seguridad, solo ADMIN escribe.


-- USUARIO: cualquiera ve el directorio basico (para selects de "asignar a", etc.);
-- cada quien edita su propio registro (campos no sensibles se controlan en el
-- service); LOGISTICA/ADMIN puede todo. Los INSERT/UPDATE con fuente=RRHH_SYNC
-- los hace SIEMPRE personal_sync.service con el cliente admin (bypassa RLS);
-- esta policy solo cubre altas/ediciones MANUALES desde la UI (ver 0007_identidad_manual.sql).


-- DOCUMENTO / DOCUMENTO_RELACION: cualquier autenticado puede subir/ver
-- (la restriccion fina de que entidad puede adjuntar que documento vive en
-- cada modulo de negocio, via document_relacion.entity_type/entity_id).


-- ============================================================
-- Fuente historica: supabase/migrations/0006_identidad_manual.sql
-- ============================================================
-- 0006_identidad_manual.sql
-- Restringe el alta/edicion MANUAL de USUARIO (fuente='MANUAL') a empresas que
-- RRHH-SYSTEM todavia no cubre, y solo para LOGISTICA/ADMIN. Ver
-- docs/04_DECISIONES.md, DEC-L002.
--
-- La lista de empresas habilitadas vive en esta tabla (no en CONFIG de la app)
-- porque RLS necesita poder consultarla en el servidor de Postgres; el
-- validator de identidad-manual en la app consulta la misma tabla, nunca una
-- copia hardcodeada.

create table if not exists ${schema}.identidad_manual_empresa_habilitada (
  company_id       uuid primary key references ${schema}.empresa(company_id),
  motivo           text not null,
  habilitado_desde timestamptz not null default now(),
  habilitado_por   uuid  -- FK a usuario, diferida (0029_fk_deferred.sql)
);

comment on table ${schema}.identidad_manual_empresa_habilitada is
  'Empresas para las que se permite alta manual de identidad mientras RRHH-SYSTEM '
  'no tenga su padron activo. Quitar la fila cuando RRHH incorpore la empresa: '
  'el upsert de personal_sync.service migra automaticamente MANUAL -> RRHH_SYNC.';


-- Seed inicial: METRIN (no existe en RRHH) y GOYDELSAC (estructura sin datos aun).
select company_id, 'RRHH-SYSTEM aun no tiene padron activo para esta empresa (2026-09-15).'
from ${schema}.empresa
where code in ('METRIN', 'GOYDELSAC')
on conflict (company_id) do nothing;

-- Reemplaza la policy generica de 0005 por una que distingue fuente=MANUAL vs RRHH_SYNC.


-- ============================================================
-- Fuente historica: supabase/migrations/0007_maestros_clasificacion.sql
-- ============================================================
-- 0007_maestros_clasificacion.sql
-- UNIDAD_MEDIDA, TIPO_PRODUCTO, FAMILIA_PRODUCTO, SUBFAMILIA_PRODUCTO (grupo MAESTROS).

create table if not exists ${schema}.unidad_medida (
  uom_id uuid primary key default gen_random_uuid(),
  code   varchar(20) not null unique,  -- UND / PAR / CAJA / MILLAR
  name   varchar(80) not null,
  active boolean not null default true
);

comment on table ${schema}.unidad_medida is 'Unidades estandarizadas y homologadas.';

create table if not exists ${schema}.tipo_producto (
  product_type_id uuid primary key default gen_random_uuid(),
  code        varchar(2) not null unique,  -- EP = EPP
  name        varchar(100) not null,
  description varchar(220),
  active      boolean not null default true
);

comment on table ${schema}.tipo_producto is
  'Catalogo del tipo principal que inicia la codificacion SKU (EP, HE, MA, EQ, etc.).';

create table if not exists ${schema}.familia_producto (
  family_id       uuid primary key default gen_random_uuid(),
  product_type_id uuid not null references ${schema}.tipo_producto(product_type_id),
  code            varchar(2) not null,  -- correlativo dentro del tipo
  name            varchar(120) not null,
  sort_order      integer,
  active          boolean not null default true,
  unique (product_type_id, code)
);

comment on table ${schema}.familia_producto is
  'Familias controladas por tipo de producto. Para EPP quedan 4 familias aprobadas.';

create table if not exists ${schema}.subfamilia_producto (
  subfamily_id uuid primary key default gen_random_uuid(),
  family_id    uuid not null references ${schema}.familia_producto(family_id),
  code         varchar(2) not null,  -- correlativo dentro de la familia
  name         varchar(120) not null,
  sort_order   integer,
  active       boolean not null default true,
  unique (family_id, code)
);

comment on table ${schema}.subfamilia_producto is
  'Subfamilias controladas dentro de cada familia; evita texto libre y duplicidades.';

-- Seed: unidades base y las 4 categorias EPP cerradas (Informe V38 Final,
-- seccion 6: 01 Cabeza/Rostro, 02 Cuerpo, 03 Ext. Superiores, 04 Ext. Inferiores).
on conflict (code) do nothing;

comment on column ${schema}.unidad_medida.code is
  'ND es un placeholder explicito: el maestro origen (833 registros consolidados a 725 SKU) '
  'no trae UOM. El catalogo se siembra con ND hasta que se complete el dato real (Informe V38 Final, seccion 6).';

on conflict (code) do nothing;

select pt.product_type_id, f.code, f.name, f.sort_order
from ${schema}.tipo_producto pt
cross join (values
  ('01', 'CABEZA / ROSTRO', 1),
  ('02', 'CUERPO', 2),
  ('03', 'EXTREMIDADES SUPERIORES', 3),
  ('04', 'EXTREMIDADES INFERIORES', 4)
) as f(code, name, sort_order)
where pt.code = 'EP'
on conflict (product_type_id, code) do nothing;

-- ============================================================
-- Fuente historica: supabase/migrations/0008_producto.sql
-- ============================================================
-- 0008_producto.sql
-- PRODUCTO, PRODUCTO_VARIANTE, PRODUCTO_IMAGEN (grupo MAESTROS).
-- producto.approved_request_id referencia SOLICITUD_MAESTRO_PRODUCTO, que se
-- crea despues (0009) -> FK diferida en 0029_fk_deferred.sql.

create table if not exists ${schema}.producto (
  product_id      uuid primary key default gen_random_uuid(),
  sku_base        varchar(50) not null unique,
  product_type_id uuid not null references ${schema}.tipo_producto(product_type_id),
  family_id       uuid not null references ${schema}.familia_producto(family_id),
  subfamily_id    uuid not null references ${schema}.subfamilia_producto(subfamily_id),
  name            varchar(220) not null,
  base_uom_id     uuid not null references ${schema}.unidad_medida(uom_id),
  supply_class    varchar(30) not null default 'ORDINARIO_BAJA'
                    check (supply_class in ('ORDINARIO_ALTA', 'ORDINARIO_BAJA', 'EXTRAORDINARIO')),
  requires_calibration     varchar(10) not null default 'NO' check (requires_calibration in ('SI','NO','NA')),
  is_asset                 boolean not null default false,
  serial_control            boolean not null default false,
  requires_weight_control   boolean not null default false,
  is_customized             boolean not null default false,
  active                    boolean not null default true,

  approved_request_id uuid,  -- FK a solicitud_maestro_producto, diferida
  approved_by          uuid references ${schema}.usuario(user_id),
  approved_at          timestamptz
);

comment on table ${schema}.producto is
  'Maestro unico de productos (725 SKU consolidados V38 Final). Alta/modificacion '
  'SOLO via SOLICITUD_MAESTRO_PRODUCTO aprobada por Logistica (ver 0009 y 0010_solicitud_maestro_producto.sql).';

create table if not exists ${schema}.producto_variante (
  variant_id             uuid primary key default gen_random_uuid(),
  product_id             uuid not null references ${schema}.producto(product_id),
  attribute_type         varchar(40) check (attribute_type in ('TALLA','COLOR','MODELO','CLASE','CLASE + TALLA','OTRO')),
  attribute_value        varchar(80),
  attribute_code         varchar(20) not null default '00',  -- '00' si no tiene atributo
  internal_variant_code  varchar(80) not null unique,
  active                 boolean not null default true
);

comment on table ${schema}.producto_variante is 'Talla/color/atributo principal sin alterar el SKU base.';

create table if not exists ${schema}.producto_imagen (
  product_image_id uuid primary key default gen_random_uuid(),
  product_id   uuid not null references ${schema}.producto(product_id),
  variant_id   uuid references ${schema}.producto_variante(variant_id),
  document_id  uuid not null references ${schema}.documento(document_id),
  is_primary   boolean not null default false,
  alt_text     varchar(220),
  display_order integer not null default 0,
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  created_by   uuid not null references ${schema}.usuario(user_id)
);

comment on table ${schema}.producto_imagen is
  'Imagenes de producto/variante. El archivo fisico va a storage; aqui solo la referencia a DOCUMENTO.';

-- Solo una imagen principal activa por producto+variante (RN del Excel 16_Producto_Imagen_V32).
create unique index if not exists uq_producto_imagen_principal
  on ${schema}.producto_imagen (product_id, coalesce(variant_id, '00000000-0000-0000-0000-000000000000'))
  where is_primary = true and active = true;

-- ============================================================
-- Fuente historica: supabase/migrations/0009_solicitud_maestro_producto.sql
-- ============================================================
-- 0009_solicitud_maestro_producto.sql
-- SOLICITUD_MAESTRO_PRODUCTO (grupo MAESTROS). Unica puerta de entrada para
-- crear/modificar/inactivar PRODUCTO (RN: "no crear producto directamente").

create table if not exists ${schema}.solicitud_maestro_producto (
  product_master_request_id uuid primary key default gen_random_uuid(),
  request_code varchar(50) not null unique,
  request_type varchar(30) not null
    check (request_type in ('ALTA_PRODUCTO','NUEVA_VARIANTE','MODIFICACION','INACTIVACION')),
  company_id   uuid not null references ${schema}.empresa(company_id),
  requested_by uuid not null references ${schema}.usuario(user_id),
  requested_at timestamptz not null default now(),

  proposed_product_type_id uuid not null references ${schema}.tipo_producto(product_type_id),
  proposed_family_id       uuid not null references ${schema}.familia_producto(family_id),
  proposed_subfamily_id    uuid not null references ${schema}.subfamilia_producto(subfamily_id),
  proposed_name            varchar(220) not null,
  proposed_uom_id           uuid not null references ${schema}.unidad_medida(uom_id),
  proposed_attribute_type  varchar(40) check (proposed_attribute_type in ('TALLA','COLOR','MODELO','OTRO')),
  proposed_attribute_value varchar(80),

  technical_description text,
  justification         text not null,
  document_id            uuid references ${schema}.documento(document_id),

  duplicate_check_status varchar(30) not null default 'SIN_COINCIDENCIA'
    check (duplicate_check_status in ('SIN_COINCIDENCIA','POSIBLE_DUPLICADO','DUPLICADO')),
  status varchar(40) not null default 'BORRADOR'
    check (status in (
      'BORRADOR','PENDIENTE_APROBACION_LOGISTICA','OBSERVADO','RECHAZADO','APROBADO','DUPLICADO'
    )),
  reviewed_by      uuid references ${schema}.usuario(user_id),
  reviewed_at      timestamptz,
  review_comment   text,
  generated_product_id uuid references ${schema}.producto(product_id)
);

comment on table ${schema}.solicitud_maestro_producto is
  'Solicitud de alta/modificacion/inactivacion de producto; solo Logistica aprueba y activa el maestro.';

create index if not exists idx_solicitud_maestro_producto_status
  on ${schema}.solicitud_maestro_producto (status);

-- ============================================================
-- Fuente historica: supabase/migrations/0010_configuracion_reglas.sql
-- ============================================================
-- 0010_configuracion_reglas.sql
-- MONEDA, TIPO_CAMBIO, REGLA_APROBACION, REGLA_DOCUMENTARIA, REGLA_PENALIDAD,
-- REGLA_CAJA_CHICA, CATALOGO_ESTADO (grupo CONFIGURACION).
--
-- Estas reglas son la implementacion de las decisiones de negocio pendientes
-- (docs/04_DECISIONES.md, PD-01..PD-08): valores CONFIGURABLES, nunca
-- hardcodeados en la app. Los valores sembrados aqui son PROVISIONALES hasta
-- que Jonathan/Gerencia los validen.
--
-- regla_penalidad.supplier_id/agreement_id referencian PROVEEDORES (0012,
-- posterior) -> FK diferida en 0029_fk_deferred.sql.

create table if not exists ${schema}.moneda (
  currency_code varchar(3) primary key,  -- PEN / USD
  name          varchar(80) not null,
  active        boolean not null default true
);

comment on table ${schema}.moneda is 'Catalogo de monedas.';

create table if not exists ${schema}.tipo_cambio (
  exchange_rate_id uuid primary key default gen_random_uuid(),
  rate_date     date not null,
  currency_code varchar(3) not null references ${schema}.moneda(currency_code),
  rate_type     varchar(20) not null check (rate_type in ('COMPRA','VENTA','CONTABLE')),
  rate_value    numeric(12,6) not null,
  source        varchar(120),
  unique (rate_date, currency_code, rate_type)
);

comment on table ${schema}.tipo_cambio is 'Historico del tipo de cambio usado en cada operacion.';

create table if not exists ${schema}.regla_aprobacion (
  approval_rule_id uuid primary key default gen_random_uuid(),
  company_id      uuid references ${schema}.empresa(company_id),  -- null = regla corporativa
  process         varchar(40) not null check (process in ('REQUERIMIENTO','COMPRA','CAJA_CHICA','CONVENIO')),
  amount_from     numeric(14,2),
  amount_to       numeric(14,2),
  supplier_type   varchar(30),
  supply_class    varchar(30),
  requires_approval        boolean not null default true,
  approver_permission_code varchar(80),
  priority        integer not null default 100,
  active          boolean not null default true
);

comment on table ${schema}.regla_aprobacion is
